describe("doctests of sympy.matrices.expressions.diagonal", () => {
  it("D[1, 2]", () => {
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }))).at(1, 2))).toBe('0');
  });
  it("D[1, 1]", () => {
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }))).at(1, 1))).toBe('x[1, 1]');
  });
  it("D.diagonal_length", () => {
    expect(sympyStr(Rational.of(2n, 1n, { gcd: 1n }))).toBe('2');
  });
  it("DiagonalMatrix(MatrixSymbol('x', n + 1, n)).diagonal_length", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(n)).toBe('n');
  });
  it("tall.diagonal_length", () => {
    expect(sympyStr(Rational.of(3n, 1n, { gcd: 1n }))).toBe('3');
  });
  it("tall[10, 1]", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', n, Rational.of(3n, 1n, { gcd: 1n }))).at(10, 1))).toBe('0');
  });
  it("diag.shape", () => {
    expect(sympyStr([Rational.of(2n, 1n, { gcd: 1n }), S.One], 't')).toBe('(2, 1)');
  });
  it("diag.diagonal_length", () => {
    expect(sympyStr(Rational.of(2n, 1n, { gcd: 1n }))).toBe('2');
  });
  it("DiagonalOf(MatrixSymbol('x', n + 1, n)).diagonal_length", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(n)).toBe('n');
  });
  it("dtall.diagonal_length", () => {
    expect(sympyStr(Rational.of(3n, 1n, { gcd: 1n }))).toBe('3');
  });
});

